// src/client.ts
var AwarizonClient = class {
  constructor(endpoint = DEFAULT_ENDPOINT) {
    this.api = null;
    this.endpoint = endpoint;
  }
  async connect() {
    if (this.api?.isConnected) return this.api;
    const provider = new WsProvider(this.endpoint);
    this.api = await ApiPromise.create({
      provider,
      types: awarizonTypes,
      rpc: awarizonRpc
    });
    await this.api.isReady;
    return this.api;
  }
  async disconnect() {
    if (this.api) {
      await this.api.disconnect();
      this.api = null;
    }
  }
  getApi() {
    if (!this.api?.isConnected) {
      throw new Error("Not connected. Call connect() first.");
    }
    return this.api;
  }
  async subscribeNewBlocks(callback) {
    const api = this.getApi();
    const unsub = await api.rpc.chain.subscribeNewHeads((header) => {
      callback(header.number.toNumber(), header.hash.toHex());
    });
    return unsub;
  }
  async getBalance(address) {
    const api = this.getApi();
    const account = await api.query.system.account(address);
    return BigInt(account.data.free.toString());
  }
};
async function connect(endpoint = DEFAULT_ENDPOINT) {
  const client = new AwarizonClient(endpoint);
  await client.connect();
  return client;
}

// src/utils.ts
function formatRiz(planck, decimals = 4) {
  const whole = planck / RIZ;
  const remainder = planck % RIZ;
  const decStr = remainder.toString().padStart(12, "0").slice(0, decimals);
  return `${whole}.${decStr}`;
}
function parseRiz(riz) {
  const [whole, decimal = ""] = riz.split(".");
  const paddedDecimal = decimal.padEnd(12, "0").slice(0, 12);
  return BigInt(whole) * RIZ + BigInt(paddedDecimal);
}
function hexToBytes(hex) {
  const clean = hex.replace("0x", "");
  return new Uint8Array(
    clean.match(/.{1,2}/g)?.map((b) => parseInt(b, 16)) ?? []
  );
}
function bytesToHex(bytes) {
  return "0x" + Array.from(bytes).map((b) => b.toString(16).padStart(2, "0")).join("");
}
function generateCampaignId(manifestHash) {
  const timestamp = Date.now().toString(16).padStart(16, "0");
  const hashPart = manifestHash.replace("0x", "").slice(0, 48);
  return "0x" + hashPart + timestamp;
}
function isValidAddress(address) {
  return address.length >= 46 && address.length <= 48;
}
function blocksToTime(blocks) {
  const seconds = blocks * 3;
  if (seconds < 60) return `${seconds}s`;
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m`;
  if (seconds < 86400) return `${Math.floor(seconds / 3600)}h`;
  return `${Math.floor(seconds / 86400)}d`;
}
function parsePlanckString(value) {
  return BigInt(value);
}

